@dataclass
class Art:
    source: str
    minutes_ago: int
    title: str
    body: str
    cite: list[str] = field(default_factory=list)


def _shuffle_sentences(body: str, seed: int) -> str:
    parts = [p.strip() for p in body.replace("\n", " ").split(". ") if p.strip()]
    rnd = random.Random(seed)
    head, tail = parts[:1], parts[1:]
    rnd.shuffle(tail)
    return ". ".join(head + tail).rstrip(".") + "."


